#include <vector>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    std::vector<int> assignElements(std::vector<int>& groups, std::vector<int>& elements) {
        int max_group = *std::max_element(groups.begin(), groups.end());
        std::vector<int> first_idx(max_group + 1, -1);

        for (int idx = 0; idx < (int)elements.size(); ++idx) {
            int val = elements[idx];
            if (val <= max_group && first_idx[val] == -1) {
                first_idx[val] = idx;
            }
        }

        std::vector<int> best(max_group + 1, -1);
        for (int val = 1; val <= max_group; ++val) {
            int idx = first_idx[val];
            if (idx == -1) continue;
            for (int multiple = val; multiple <= max_group; multiple += val) {
                if (best[multiple] == -1 || idx < best[multiple]) {
                    best[multiple] = idx;
                }
            }
        }

        std::vector<int> ans(groups.size());
        for (size_t i = 0; i < groups.size(); ++i) {
            ans[i] = best[groups[i]];
        }
        return ans;
    }
};

import java.util.Arrays;

class Solution {
    public int[] assignElements(int[] groups, int[] elements) {
        int maxGroup = 0;
        for (int g : groups) maxGroup = Math.max(maxGroup, g);

        int[] firstIdx = new int[maxGroup + 1];
        Arrays.fill(firstIdx, -1);
        for (int idx = 0; idx < elements.length; idx++) {
            int val = elements[idx];
            if (val <= maxGroup && firstIdx[val] == -1) {
                firstIdx[val] = idx;
            }
        }

        int[] best = new int[maxGroup + 1];
        Arrays.fill(best, -1);
        for (int val = 1; val <= maxGroup; val++) {
            int idx = firstIdx[val];
            if (idx == -1) continue;
            for (int multiple = val; multiple <= maxGroup; multiple += val) {
                if (best[multiple] == -1 || idx < best[multiple]) {
                    best[multiple] = idx;
                }
            }
        }

        int[] ans = new int[groups.length];
        for (int i = 0; i < groups.length; i++) {
            ans[i] = best[groups[i]];
        }
        return ans;
    }
}

var assignElements = function(groups, elements) {
    let maxGroup = 0;
    for (let i = 0; i < groups.length; i++) {
        if (groups[i] > maxGroup) maxGroup = groups[i];
    }

    const firstIdx = new Int32Array(maxGroup + 1).fill(-1);
    for (let idx = 0; idx < elements.length; idx++) {
        const val = elements[idx];
        if (val <= maxGroup && firstIdx[val] === -1) {
            firstIdx[val] = idx;
        }
    }

    const best = new Int32Array(maxGroup + 1).fill(-1);
    for (let val = 1; val <= maxGroup; val++) {
        const idx = firstIdx[val];
        if (idx === -1) continue;
        for (let multiple = val; multiple <= maxGroup; multiple += val) {
            if (best[multiple] === -1 || idx < best[multiple]) {
                best[multiple] = idx;
            }
        }
    }

    const ans = new Int32Array(groups.length);
    for (let i = 0; i < groups.length; i++) {
        ans[i] = best[groups[i]];
    }
    return Array.from(ans);
};
